// Patient create/edit form. Per PAT-01 (create) + PAT-03 (edit).
// Uses react-hook-form + zod resolver against patientInput / patientPatchInput.
//
// Quick task 20260812 — auto-MRN: MRN is auto-generated by the repo at
// insert time (migration 0008 + nextMrn()). The form no longer carries an
// MRN input on either Create or Edit. EditForm surfaces the existing
// MRN as a read-only label above the form.
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useForm, Controller, type UseFormReturn } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import type { z } from 'zod';
import { ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import EmptyStateCard from '@/components/EmptyStateCard';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useRoute } from '@/lib/router';
import { safeInvoke } from '@/lib/ipc-result';
import { toast } from 'sonner';
import { patientInput, patientPatchInput } from '@shared/validators';

type Props = {
  mode: 'create' | 'edit';
  patientId?: string;
};

type CreateValues = z.infer<typeof patientInput>;
type PatchValues = z.infer<typeof patientPatchInput>;

const GENDER_VALUES = ['__none__', 'male', 'female', 'other'] as const;
type GenderValue = (typeof GENDER_VALUES)[number];

export default function PatientForm({ mode, patientId }: Props): JSX.Element {
  const { t } = useTranslation();
  const { navigate } = useRoute();
  const [submitting, setSubmitting] = useState(false);
  const [loaded, setLoaded] = useState(mode === 'create');
  // Plan 08-10 / G-08-4 — render <EmptyStateCard> instead of crashing
  // when the IPC gate returns {ok:false}.
  const [gated, setGated] = useState(false);

  const isCreate = mode === 'create';

  const createForm = useForm<CreateValues>({
    resolver: zodResolver(patientInput),
    defaultValues: { fullName: '', dob: '', gender: null, phone: null, notes: null },
  });

  const editForm = useForm<PatchValues>({
    resolver: zodResolver(patientPatchInput),
    defaultValues: { fullName: '', dob: '', gender: null, phone: null, notes: null },
  });

  // Load existing patient in edit mode.
  useEffect(() => {
    if (mode === 'edit' && patientId) {
      void (async () => {
        const row = await safeInvoke(window.api.patients.get(patientId));
        if (row === null) {
          // Plan 08-10 / G-08-4 — could be gate rejection (license
          // invalid/expired) OR a legitimate patient-not-found. Render
          // the gated empty state in either case; do NOT navigate
          // away (the LicenseGate modal sits above the empty state).
          setGated(true);
          setLoaded(true);
          return;
        }
        editForm.reset({
          fullName: row.fullName,
          dob: row.dob,
          gender: row.gender,
          phone: row.phone,
          notes: row.notes,
        });
        setLoaded(true);
      })();
    }
  }, [mode, patientId, editForm, navigate]);

  if (!loaded) {
    return (
      <main className="min-h-screen grid place-items-center bg-slate-50">
        <p className="text-sm text-slate-500">{t('patientForm.loading')}</p>
      </main>
    );
  }

  if (gated) {
    return (
      <main className="min-h-screen bg-slate-50 p-6">
        <div className="mx-auto max-w-xl flex flex-col gap-4">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => navigate({ name: 'patients' })}
            className="self-start"
          >
            <ArrowLeft className="size-4 mr-1" />
            {t('patientForm.backToPatients')}
          </Button>
          <EmptyStateCard />
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-50 p-6">
      <div className="mx-auto max-w-xl flex flex-col gap-4">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={() => navigate({ name: 'patients' })}
          className="self-start"
        >
          <ArrowLeft className="size-4 mr-1" />
          {t('patientForm.backToPatients')}
        </Button>
        <Card>
          <CardHeader>
            <CardTitle>{isCreate ? t('patientForm.pageTitleNew') : t('patientForm.pageTitleEdit')}</CardTitle>
          </CardHeader>
          <CardContent>
            {isCreate ? (
              <CreateForm
                form={createForm}
                submitting={submitting}
                setSubmitting={setSubmitting}
              />
            ) : (
              <EditForm
                form={editForm}
                patientId={patientId!}
                submitting={submitting}
                setSubmitting={setSubmitting}
              />
            )}
          </CardContent>
        </Card>
      </div>
    </main>
  );
}

type CreateFormProps = {
  form: UseFormReturn<CreateValues>;
  submitting: boolean;
  setSubmitting: (v: boolean) => void;
};

function CreateForm({ form, submitting, setSubmitting }: CreateFormProps): JSX.Element {
  const { t } = useTranslation();
  const { navigate } = useRoute();
  const { handleSubmit, register, control, formState: { errors } } = form;

  async function onSubmit(values: CreateValues): Promise<void> {
    setSubmitting(true);
    try {
      // mrn is auto-generated by the repo (nextMrn); renderer never sends it.
      await window.api.patients.create({
        fullName: values.fullName,
        dob: values.dob,
        gender: values.gender ?? null,
        phone: values.phone ?? null,
        notes: values.notes ?? null,
      });
      toast.success(t('patientForm.successCreate'));
      navigate({ name: 'patients' });
    } catch (err) {
      const msg = err instanceof Error ? err.message : t('patientForm.failedCreate');
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  }

  function genderLabel(value: GenderValue): string {
    if (value === '__none__') return '—';
    if (value === 'male') return t('patientForm.genderMale');
    if (value === 'female') return t('patientForm.genderFemale');
    return t('patientForm.genderOther');
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4" noValidate>
      <Field label={t('patientForm.fullName')} id="fullName" error={errors.fullName?.message}>
        <Input id="fullName" autoComplete="name" {...register('fullName')} aria-invalid={!!errors.fullName} />
      </Field>
      <Field label={t('patientForm.dob')} id="dob" error={errors.dob?.message}>
        <Input id="dob" type="date" {...register('dob')} aria-invalid={!!errors.dob} />
      </Field>
      <Field label={t('patientForm.gender')} id="gender" error={errors.gender?.message}>
        <Controller
          control={control}
          name="gender"
          render={({ field }) => {
            const value = (field.value ?? '__none__') as string;
            return (
              <Select
                value={value}
                onValueChange={(v) => field.onChange(v === '__none__' ? null : v)}
              >
                <SelectTrigger id="gender">
                  <SelectValue placeholder="—" />
                </SelectTrigger>
                <SelectContent>
                  {GENDER_VALUES.map((o) => (
                    <SelectItem key={o} value={o}>
                      {genderLabel(o)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            );
          }}
        />
      </Field>
      <Field label={t('patientForm.phone')} id="phone" error={errors.phone?.message}>
        <Input id="phone" {...register('phone')} />
      </Field>
      <Field label={t('patientForm.notes')} id="notes" error={errors.notes?.message}>
        <textarea
          id="notes"
          className="flex min-h-20 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          {...register('notes')}
        />
      </Field>
      <Button type="submit" disabled={submitting} className="mt-2">
        {submitting ? t('patientForm.submitSaving') : t('patientForm.submitCreate')}
      </Button>
    </form>
  );
}

type EditFormProps = {
  form: UseFormReturn<PatchValues>;
  patientId: string;
  submitting: boolean;
  setSubmitting: (v: boolean) => void;
};

function EditForm({ form, patientId, submitting, setSubmitting }: EditFormProps): JSX.Element {
  const { t } = useTranslation();
  const { navigate } = useRoute();
  const { handleSubmit, register, control, formState: { errors } } = form;
  // Auto-fetch the patient's existing MRN to render as a read-only label.
  // MRN is generated by the repo and never editable (validator strips it).
  const [existingMrn, setExistingMrn] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      // Plan 08-10 / G-08-4 — branch on null even for the secondary
      // patients.get call so the gate rejection doesn't crash here.
      const row = await safeInvoke(window.api.patients.get(patientId));
      if (cancelled) return;
      if (row !== null) setExistingMrn(row.mrn);
    })();
    return () => {
      cancelled = true;
    };
  }, [patientId]);

  async function onSubmit(values: PatchValues): Promise<void> {
    setSubmitting(true);
    try {
      const patch: PatchValues = {};
      if (values.fullName !== undefined) patch.fullName = values.fullName;
      if (values.dob !== undefined) patch.dob = values.dob;
      if (values.gender !== undefined) patch.gender = values.gender;
      if (values.phone !== undefined) patch.phone = values.phone;
      if (values.notes !== undefined) patch.notes = values.notes;

      await window.api.patients.update(patientId, patch);
      toast.success(t('patientForm.successUpdate'));
      navigate({ name: 'patients' });
    } catch (err) {
      const msg = err instanceof Error ? err.message : t('patientForm.failedUpdate');
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  }

  function genderLabel(value: GenderValue): string {
    if (value === '__none__') return '—';
    if (value === 'male') return t('patientForm.genderMale');
    if (value === 'female') return t('patientForm.genderFemale');
    return t('patientForm.genderOther');
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4" noValidate>
      {existingMrn !== null ? (
        <div
          className="flex flex-col gap-1 rounded-md border border-slate-200 bg-slate-50 px-3 py-2"
          data-testid="patient-mrn-readonly"
        >
          <span className="text-xs font-semibold uppercase tracking-[0.2em] text-muted-foreground">
            {t('patientForm.mrnLabel')}
          </span>
          <span className="font-mono text-sm">{existingMrn}</span>
        </div>
      ) : null}
      <Field label={t('patientForm.fullName')} id="fullName" error={errors.fullName?.message}>
        <Input id="fullName" autoComplete="name" {...register('fullName')} aria-invalid={!!errors.fullName} />
      </Field>
      <Field label={t('patientForm.dob')} id="dob" error={errors.dob?.message}>
        <Input id="dob" type="date" {...register('dob')} aria-invalid={!!errors.dob} />
      </Field>
      <Field label={t('patientForm.gender')} id="gender" error={errors.gender?.message}>
        <Controller
          control={control}
          name="gender"
          render={({ field }) => {
            const value = (field.value ?? '__none__') as string;
            return (
              <Select
                value={value}
                onValueChange={(v) => field.onChange(v === '__none__' ? null : v)}
              >
                <SelectTrigger id="gender">
                  <SelectValue placeholder="—" />
                </SelectTrigger>
                <SelectContent>
                  {GENDER_VALUES.map((o) => (
                    <SelectItem key={o} value={o}>
                      {genderLabel(o)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            );
          }}
        />
      </Field>
      <Field label={t('patientForm.phone')} id="phone" error={errors.phone?.message}>
        <Input id="phone" {...register('phone')} />
      </Field>
      <Field label={t('patientForm.notes')} id="notes" error={errors.notes?.message}>
        <textarea
          id="notes"
          className="flex min-h-20 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          {...register('notes')}
        />
      </Field>
      <Button type="submit" disabled={submitting} className="mt-2">
        {submitting ? t('patientForm.submitSaving') : t('patientForm.submitUpdate')}
      </Button>
    </form>
  );
}

function Field({ label, id, error, children }: { label: string; id: string; error?: string; children: React.ReactNode }): JSX.Element {
  return (
    <div className="flex flex-col gap-2">
      <Label htmlFor={id}>{label}</Label>
      {children}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}
